  61 => 
  array (
    'question_text' => 'An LCSW is preparing copies of a former client’s record and calculates the charge for producing and transmitting the requested material.Which fee approach is most appropriate?',
    'option_a' => 'The LCSW may charge any amount stated in the practice’s informed-consent form',
    'option_b' => 'The LCSW may add a penalty when the client has an unpaid treatment balance',
