  63 => 
  array (
    'question_text' => 'After a client dies, the client’s sibling asks the LCSW for the complete record and explains that the family wants to understand what happened.What should the LCSW do?',
    'option_a' => 'Release the record because confidentiality ends at death',
    'option_b' => 'Release only the final progress note',
